import React, { useState, useEffect } from 'react';

const API_URL = 'http://127.0.0.1:8000/api';
function ModelManagement() {
    const [models, setModels] = useState([]);
    const [training, setTraining] = useState(false);
    const [trainingStatus, setTrainingStatus] = useState('');

    useEffect(() => {
        fetch(`${API_URL}/mlflow/models`)
            .then(res => res.json())
            .then(data => setModels(data))
            .catch(err => console.error("Failed to fetch models", err));
    }, []);

    const handleRetrainModel = () => {
        setTraining(true);
        setTrainingStatus('Initiating training...');
        // Simulate starting a training process
        setTimeout(() => {
            // Simulate a successful training
            setTrainingStatus('Training completed successfully!');
            setTraining(false);
            // Optionally refresh models after training
            fetch(`${API_URL}/mlflow/models`)
                .then(res => res.json())
                .then(data => setModels(data))
                .catch(err => console.error("Failed to fetch models", err));
        }, 5000); // Simulate 5 seconds of training
    };

    return (
        <div className="card">
            <h2>Current Deployed Model</h2>
            <p>This section shows the model currently in production use by the main server.</p>
            <button onClick={handleRetrainModel} disabled={training}>
                {training ? 'Training...' : 'Retrain Model'}
            </button>
            {trainingStatus && <p>{trainingStatus}</p>}
            <h3>Deployed Model Details</h3>
            <table>
                <thead>
                    <tr>
                        <th>Name</th>
                        <th>Version (Last Modified)</th>
                        <th>Status</th>
                    </tr>
                </thead>
                <tbody>
                    {models.map(m => (
                        <tr key={m.name}>
                            <td>{m.name}</td>
                            <td>{m.version}</td>
                            <td>{m.stage}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}
export default ModelManagement;
